public.auto_populate_meter_reading_field:
DECLARE
  v_meter RECORD;
BEGIN
  -- Only populate if meter_id is provided
  IF NEW.meter_id IS NOT NULL THEN
    SELECT building_id, room_id, meter_type, service_id
    INTO v_meter
    FROM meters
    WHERE id = NEW.meter_id;

    IF FOUND THEN
      NEW.building_id := v_meter.building_id;
      NEW.room_id := v_meter.room_id;
      NEW.meter_type := v_meter.meter_type;
      NEW.service_id := v_meter.service_id;
    END IF;
  END IF;

  -- Auto-populate settlement_month from reading_date (YYYY-MM)
  IF NEW.reading_date IS NOT NULL THEN
    NEW.settlement_month := TO_CHAR(NEW.reading_date, 'YYYY-MM');
  END IF;

  -- Auto-populate recorded_by from auth.uid()
  NEW.recorded_by := auth.uid();

  RETURN NEW;
END;

public.auto_populate_previous_reading:
DECLARE
  v_previous DECIMAL(10, 2);
BEGIN
  IF NEW.meter_id IS NOT NULL THEN
    -- Try to get the most recent reading for this meter
    SELECT current_reading
    INTO v_previous
    FROM meter_readings
    WHERE meter_id = NEW.meter_id
      AND deleted_at IS NULL
    ORDER BY reading_date DESC, created_at DESC
    LIMIT 1;

    IF FOUND THEN
      NEW.previous_reading := v_previous;
    ELSE
      -- No previous reading → use initial_reading from meters
      SELECT initial_reading
      INTO v_previous
      FROM meters
      WHERE id = NEW.meter_id;

      IF FOUND AND v_previous IS NOT NULL THEN
        NEW.previous_reading := v_previous;
      ELSE
        NEW.previous_reading := 0;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;

public.auto_generate_reading_code:
DECLARE
  v_prefix   TEXT;
  v_next_seq INT;
BEGIN
  IF NEW.reading_code IS NOT NULL AND NEW.reading_code <> '' THEN
    RETURN NEW;
  END IF;

  v_prefix := 'CSS' || TO_CHAR(NEW.reading_date, 'YYMM');

  PERFORM pg_advisory_xact_lock(hashtext(v_prefix));

  SELECT COALESCE(MAX(CAST(substring(reading_code FROM length(v_prefix) + 1) AS INT)), 0) + 1
    INTO v_next_seq
    FROM meter_readings
   WHERE reading_code LIKE v_prefix || '%'
     AND substring(reading_code FROM length(v_prefix) + 1) ~ '^[0-9]+$';

  NEW.reading_code := v_prefix || LPAD(v_next_seq::TEXT, 5, '0');
  RETURN NEW;
END;

public.set_user_id_from_auth:
BEGIN
  IF NEW.user_id IS NULL THEN
    NEW.user_id := auth.uid();
  END IF;
  RETURN NEW;
END;

app_private.guard_meter_reading_boundary:
BEGIN
  IF NEW.boundary_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contract_meter_boundaries b WHERE b.id=NEW.boundary_id AND b.organization_id=NEW.organization_id
    AND b.contract_id=NEW.contract_id AND b.room_id=NEW.room_id AND b.building_id=NEW.building_id AND b.meter_id=NEW.meter_id) THEN
    RAISE EXCEPTION 'Monthly reading boundary subject mismatch' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END
